def write_gds(output_path: str = None) -> str:
    """Write the embedded layout to a GDS file and return the path."""
    if output_path is None:
        output_path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                   "snail.gds")

    gdspy.current_library = gdspy.GdsLibrary()
    cell = gdspy.Cell("LAYOUT")

    for layer, polys in POLYGONS.items():
        for pts in polys:
            cell.add(gdspy.Polygon(pts, layer=layer))

    gdspy.write_gds(output_path)
    print(f"GDS written → {output_path}")
    return output_path


if __name__ == "__main__":
    import sys
    out = sys.argv[1] if len(sys.argv) > 1 else None
    write_gds(out)
